import{_ as e,o as n,c as s,a5 as i}from"./chunks/framework.D_J2JZBr.js";const u=JSON.parse('{"title":"论文阅读与讨论组","description":"用三遍读法、证据笔记与结构化讨论，把论文从读过变成真正理解。","frontmatter":{"title":"论文阅读与讨论组","description":"用三遍读法、证据笔记与结构化讨论，把论文从读过变成真正理解。"},"headers":[],"relativePath":"research/paper-reading.md","filePath":"research/paper-reading.md","lastUpdated":1795531638000}'),r={name:"research/paper-reading.md"};function p(l,a,t,o,c,h){return n(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="论文阅读与讨论组" tabindex="-1">论文阅读与讨论组 <a class="header-anchor" href="#论文阅读与讨论组" aria-label="Permalink to &quot;论文阅读与讨论组&quot;">​</a></h1><p>读论文的目标不是逐句翻译，而是理解“作者为什么这样做、证据支持到哪里、我能如何验证”。先明确阅读目的：了解领域、寻找基线、复现方法，还是为某个设计决策找依据。不同目的需要不同深度，不必每篇都精读。</p><h2 id="三遍读法" tabindex="-1">三遍读法 <a class="header-anchor" href="#三遍读法" aria-label="Permalink to &quot;三遍读法&quot;">​</a></h2><h3 id="第一遍-建立地图" tabindex="-1">第一遍：建立地图 <a class="header-anchor" href="#第一遍-建立地图" aria-label="Permalink to &quot;第一遍：建立地图&quot;">​</a></h3><p>用约 10–20 分钟看标题、摘要、引言、主要图表和结论，暂时跳过推导。回答七个问题：解决什么问题、为什么难、现有方法哪里不够、关键观察是什么、核心机制是什么、哪个结果最有说服力、有哪些前提与局限。最后写一句自己的总结，再决定是否继续。</p><p>标题中的“高效”“可扩展”不是结论。必须追问：相对哪个基线，在什么设置下，用什么指标？看不懂的术语先记入清单，不要被一个生词拖住全部阅读。</p><h3 id="第二遍-追踪机制与证据" tabindex="-1">第二遍：追踪机制与证据 <a class="header-anchor" href="#第二遍-追踪机制与证据" aria-label="Permalink to &quot;第二遍：追踪机制与证据&quot;">​</a></h3><p>按数据流阅读方法，把总体框架拆成“输入 → 操作 → 输出 → 有效原因 → 代价”。定义公式中的符号、单位、假设与边界条件。逐张检查关键图表，区分论文原文事实、帮助理解的解释、自己的推断。</p><p>IC 论文尤其需要记录技术节点、供电电压、频率、面积、功耗、存储容量、位宽、工作负载和测试条件。区分实测、后仿真、综合估计与理论分析；峰值吞吐不能直接当端到端速度，跨工艺归一化也不能自动证明公平。</p><h3 id="第三遍-尝试重建" tabindex="-1">第三遍：尝试重建 <a class="header-anchor" href="#第三遍-尝试重建" aria-label="Permalink to &quot;第三遍：尝试重建&quot;">​</a></h3><p>合上论文，画出框图、解释关键推导，或实现最小模型。复现前固定论文版本、代码提交、依赖与配置，先运行作者基线，再改一个变量。若结果不符，记录差异和排查过程，不通过换口径把数字“对齐”。</p><p>第三遍不一定意味着完整流片。重算一个关键表格、复现一段算法、构造反例，都是检验理解的方法。明确哪些内容已经验证，哪些只是相信作者的报告。</p><h2 id="可复制的阅读模板" tabindex="-1">可复制的阅读模板 <a class="header-anchor" href="#可复制的阅读模板" aria-label="Permalink to &quot;可复制的阅读模板&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>论文：标题、作者、年份、会议/期刊、版本、DOI 或原文链接</span></span>
<span class="line"><span>阅读目的：这篇论文要帮我回答什么？</span></span>
<span class="line"><span>一句话：在什么条件下，用什么机制解决什么问题？</span></span>
<span class="line"><span>背景与缺口：已有方法的能力和具体瓶颈</span></span>
<span class="line"><span>方法：输入 → 操作 → 输出 → 为什么有效 → 代价</span></span>
<span class="line"><span>关键证据：Figure / Table / Section 与对应结论</span></span>
<span class="line"><span>实验条件：工艺/平台、频率、精度、工作负载、基线、测量范围</span></span>
<span class="line"><span>局限：原文承认的问题 / 自己尚未验证的判断</span></span>
<span class="line"><span>复现记录：版本、配置、命令、日志位置、结果与偏差</span></span>
<span class="line"><span>横向比较：与已读工作的共同假设和关键差别</span></span>
<span class="line"><span>待解问题：哪些结论仍缺证据？</span></span>
<span class="line"><span>下一次第一步：一个能立即开始的小任务</span></span></code></pre></div><p>笔记不必复制论文目录。重要的是让未来的自己能找到原始依据。数字要回原表核查；预印本与正式版可能不同，不能混用两个版本的结果。引用原图时标明出处，自己重画的解释图不能冒充作者实验。</p><h2 id="如何组织-reading-group-journal-club" tabindex="-1">如何组织 reading group / journal club <a class="header-anchor" href="#如何组织-reading-group-journal-club" aria-label="Permalink to &quot;如何组织 reading group / journal club&quot;">​</a></h2><p>读书组（Reading Group）适合围绕连续主题逐步补齐知识；期刊俱乐部（Journal Club）可围绕单篇新工作讨论。不论名称，都应先选一个问题，而不是只追逐最新论文。</p><ul><li><strong>会前</strong>：明确主讲、主持和记录角色，提前分享原文版本、必读图表与两三个问题。主讲者准备背景，参与者至少完成第一遍阅读。</li><li><strong>会中</strong>：可按 45–60 分钟组织：30 秒结论、问题与背景、核心方法、实验与公平性、开放讨论。时间仅是组织建议，不是固定制度。遇到推导分歧，先回到符号和假设，不用“作者肯定是对的”结束讨论。</li><li><strong>会后</strong>：纪要按“结论 → 讲懂的机制 → 未解问题 → 行动项”整理。为行动项写明负责人、产物与约定时间，但公开版应移除个人与内部项目细节。</li></ul><p>主题主页可维护一张精读表，字段为论文、问题、机制、证据、局限和复现入口；另设跨论文连接与下一次第一步。不要把聊天流水账当研究积累，也不要未经同意录音或公开组会材料。</p><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>补充读论文与组织讨论组的方法；请提交可公开的流程，不上传内部会议记录或未发表成果。</p></div><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://ccr.sigcomm.org/online/files/p83-keshavA.pdf" target="_blank" rel="noreferrer">How to Read a Paper，S. Keshav</a>：经典三遍读法。</li><li>下一步：<a href="/shanghaitech-ic-wiki-dev.github.io/research/venues">会议期刊地图</a>与<a href="/shanghaitech-ic-wiki-dev.github.io/research/writing">学术写作</a>。</li></ul>`,22)])])}const g=e(r,[["render",p]]);export{u as __pageData,g as default};
